import { sql } from 'drizzle-orm';
import { customType, pgEnum, timestamp, uuid } from 'drizzle-orm/pg-core';

// Encrypted fields are stored as ciphertext (docs/10-security-privacy.md#field-level-encryption).
export const bytea = customType<{ data: Buffer }>({ dataType: () => 'bytea' });

export const ts = (name: string) => timestamp(name, { withTimezone: true });

// Time-ordered UUID generated by PostgreSQL 18 (R-61). Callers may still supply an ID.
export const id = () => uuid().primaryKey().default(sql`uuidv7()`);

// Enum values come from @med/shared so the API and the apps share one spelling.
export function enumOf<const T extends readonly [string, ...string[]]>(name: string, values: T) {
  return pgEnum(name, values as unknown as [T[number], ...T[number][]]);
}
